/* ================= 和风主菜单排版层 r1 =================
 * 目标：只重排主菜单 MainView 的视觉层，不改游戏逻辑与其它界面。
 *   - 左侧纸色竖幅 + 右侧青绿天空，40/60 硬分割
 *   - 大日轮光晕 + 淡火柴人对砍水印
 *   - 竖排「火柴人」标题（预渲染图，不依赖设备字体）
 *   - 「2 Players」按钮改为左下茜红长条，文字预渲染
 * 关闭方式：地址栏加 ?wa=0
 */
(function () {
  "use strict";
  if (window.__waR1) return;
  if (/[?&]wa=0/.test(location.search)) return;

  var IMG = {"btn_paper":"data:image/png;base64,","btn_txt":"data:image/png;base64,","btn_wa":"data:image/png;base64,","mark":"data:image/png;base64,","paper":"data:image/png;base64,","sky":"data:image/png;base64,","sun":"data:image/png;base64,","title_wa":"data:image/png;base64,"};

  var T = window.__waR1 = { v: "wa-r1", built: 0, laid: 0, ready: 0, err: "" };
  T.report = function () {
    return { v: T.v, built: T.built, laid: T.laid, err: T.err };
  };

  var IM = {}, SF = {}, loaded = 0, total = 0, k;
  for (k in IMG) total++;
  for (k in IMG) {
    (function (nm) {
      var im = new Image();
      im.onload = function () { loaded++; if (loaded >= total) T.ready = 1; };
      im.onerror = function () { loaded++; if (loaded >= total) T.ready = 1; };
      im.src = IMG[nm];
      IM[nm] = im;
    })(k);
  }

  var INSET = { btn_wa: 20, btn_paper: 22 };

  function frame(nm) {
    if (SF[nm]) return SF[nm];
    var im = IM[nm];
    if (!im || !im.width) return null;
    try {
      var tex = new cc.Texture2D();
      tex.initWithElement(im);
      tex.handleLoadedTexture();
      var sf = new cc.SpriteFrame();
      sf.setTexture(tex);
      sf.setRect(cc.rect(0, 0, im.width, im.height));
      sf.setOriginalSize(cc.size(im.width, im.height));
      if (INSET[nm]) {
        var v = INSET[nm];
        sf.insetLeft = v; sf.insetTop = v; sf.insetRight = v; sf.insetBottom = v;
      }
      sf.name = nm;
      SF[nm] = sf;
      return sf;
    } catch (e) {
      T.err = "frame:" + nm + ":" + e.message;
      return null;
    }
  }

  function mk(parent, name, nm, w, h, opt) {
    opt = opt || {};
    var n = new cc.Node(name);
    var sp = n.addComponent(cc.Sprite);
    var sf = frame(nm);
    if (sf) sp.spriteFrame = sf;
    sp.sizeMode = cc.Sprite.SizeMode.CUSTOM;
    if (opt.tiled) sp.type = cc.Sprite.Type.TILED;
    else if (opt.sliced) sp.type = cc.Sprite.Type.SLICED;
    else sp.type = cc.Sprite.Type.SIMPLE;
    n.setContentSize(w, h);
    if (opt.color) n.color = new cc.Color(opt.color[0], opt.color[1], opt.color[2]);
    if (opt.opacity != null) n.opacity = opt.opacity;
    n.parent = parent;
    return n;
  }

  var ROOT = null, PANEL = null, SKY = null, SUN = null, MARK = null, EDGE = null, TITLE = null, BRAND = null;

  /* 把 DOM 层的 GUIDE 按钮挪到右上角，改纸白描边小方框 */
  function css() {
    if (document.getElementById("__waCss")) return;
    var st = document.createElement("style");
    st.id = "__waCss";
    st.textContent = [
      "#__guideBtnDom{left:auto!important;right:104px!important;top:16px!important;bottom:auto!important;",
      "margin:0!important;transform:none!important;",
      "background:#FAF6E7!important;border:1px solid #BCB196!important;color:#3E4A42!important;",
      "box-shadow:0 1px 2px rgba(60,66,58,.10)!important;border-radius:3px!important;",
      "font-size:15px!important;font-weight:600!important;letter-spacing:3px!important;",
      "width:92px!important;height:36px!important;padding:0!important;line-height:34px!important;}"
    ].join("");
    document.head.appendChild(st);
  }

  function findMain() {
    var mv = cc.find("Canvas/MainView");
    if (!mv || !mv.isValid || !mv.activeInHierarchy) return null;
    if (!mv.getChildByName("pvp")) return null;
    return mv;
  }

  /* 顶部小字：STICKMAN BATTLE */
  function mkBrand(parent) {
    var n = new cc.Node("__waBrand");
    var lb = n.addComponent(cc.Label);
    lb.string = "S T I C K M A N   B A T T L E";
    lb.fontSize = 24;
    lb.lineHeight = 30;
    try { lb.fontFamily = "Georgia"; } catch (e) {}
    lb.horizontalAlign = cc.Label.HorizontalAlign.LEFT;
    lb.verticalAlign = cc.Label.VerticalAlign.CENTER;
    n.anchorX = 0;
    n.color = new cc.Color(0x8a, 0x85, 0x74);
    n.opacity = 200;
    n.parent = parent;
    return n;
  }

  function build(mv) {
    var old = mv.getChildByName("__waRoot");
    if (old && old.isValid) old.destroy();
    ROOT = new cc.Node("__waRoot");
    ROOT.parent = mv;
    try { ROOT.setSiblingIndex(1); } catch (e) {}

    PANEL = mk(ROOT, "__waPanel", "paper", 780, 1080, { tiled: true });
    SKY = mk(ROOT, "__waSky", "sky", 1140, 1080, {});
    MARK = mk(ROOT, "__waMark", "mark", 760, 473, { opacity: 66 });
    SUN = mk(ROOT, "__waSun", "sun", 900, 900, { opacity: 255 });
    EDGE = mk(ROOT, "__waEdge", "paper", 3, 1080, { color: [0x9a, 0x8f, 0x72], opacity: 60 });
    TITLE = mk(ROOT, "__waTitle", "title_wa", 300, 760, {});
    BRAND = mkBrand(ROOT);

    // 原版深底 logo 让位给竖排标题
    var logo = mv.getChildByName("Title");
    if (logo) logo.active = false;

    // 顶部横条背景隐藏（只保留设置按钮），避免遮住标题
    var tp = mv.getChildByName("TopPanel");
    if (tp) {
      var tps = tp.getComponent(cc.Sprite);
      if (tps) tps.enabled = false;
    }

    // 设置按钮换纸白描边底，和右上 GUIDE 一致
    var st0 = tp && tp.getChildByName("Setting");
    if (st0) {
      var ssp = st0.getComponent(cc.Sprite);
      var psf = frame("btn_paper");
      if (ssp && psf) {
        ssp.spriteFrame = psf;
        ssp.type = cc.Sprite.Type.SLICED;
        ssp.sizeMode = cc.Sprite.SizeMode.CUSTOM;
        st0.setContentSize(96, 96);
      }
    }

    // 2 Players 卡片（原 bgPvp）淡出让位，只留长条按钮
    var card = mv.getChildByName("bgPvp");
    if (card) {
      card.opacity = 0;
      var cb = card.getComponent(cc.Button);
      if (cb) cb.interactable = false;
      card.active = false;
    }

    // 长条按钮换皮
    var pvp = mv.getChildByName("pvp");
    if (pvp) {
      var sp = pvp.getComponent(cc.Sprite);
      var sf = frame("btn_wa");
      if (sp && sf) {
        sp.spriteFrame = sf;
        sp.type = cc.Sprite.Type.SLICED;
        sp.sizeMode = cc.Sprite.SizeMode.CUSTOM;
      }
      pvp.setContentSize(596, 100);
      var lb = pvp.getChildByName("label");
      if (lb) lb.active = false;
      var bt = pvp.getChildByName("__waBtnTxt");
      if (!bt) mk(pvp, "__waBtnTxt", "btn_txt", 400, 66, {});
    }

    T.built = 1;
  }

  function layout(mv) {
    var vs;
    try { vs = cc.view.getVisibleSize(); } catch (e) { return; }
    var W = vs.width, H = vs.height;
    if (!W || !H) return;
    var leftW = Math.min(780, W * 0.407);
    var leftEdge = -W / 2;
    var splitX = leftEdge + leftW;
    var skyW = W - leftW;

    PANEL.setContentSize(leftW, H);
    PANEL.setPosition(leftEdge + leftW / 2, 0);

    SKY.setContentSize(skyW, H);
    SKY.setPosition(splitX + skyW / 2, 0);

    var sunD = Math.min(H * 1.16, skyW * 1.06);
    SUN.setContentSize(sunD, sunD);
    SUN.setPosition(splitX + skyW * 0.50, H * 0.135);

    var mw = Math.min(skyW * 0.66, 760);
    MARK.setContentSize(mw, mw * 0.622);
    MARK.setPosition(splitX + skyW * 0.49, -H * 0.165);

    EDGE.setContentSize(3, H);
    EDGE.setPosition(splitX, 0);

    TITLE.setPosition(leftEdge + leftW * 0.303, H * 0.083);

    BRAND.setPosition(leftEdge + leftW * 0.282, H * 0.452);

    var pvp = mv.getChildByName("pvp");
    if (pvp) pvp.setPosition(leftEdge + leftW * 0.626, -H * 0.278);

    T.laid++;
  }

  function tick() {
    if (typeof cc === "undefined" || !cc.director || !cc.view) return;
    var mv = findMain();
    if (!mv) return;
    if (!T.ready) return; // 贴图还没解码完，先等
    // MainView 被重建时（返回主菜单）需要重新挂载
    if (!ROOT || !ROOT.isValid || ROOT.parent !== mv) {
      T.built = 0;
      ROOT = PANEL = SKY = SUN = MARK = EDGE = TITLE = BRAND = null;
      build(mv);
    }
    if (!T.built || !ROOT || !ROOT.isValid) return;
    try { layout(mv); } catch (e) { T.err = "layout:" + e.message; }
  }

  function boot() {
    css();
    setInterval(css, 900);
    setInterval(function () {
      try { tick(); } catch (e) { T.err = "tick:" + e.message; }
    }, 400);
    setTimeout(tick, 600);
  }

  if (typeof cc !== "undefined" && cc.director && cc.director.getScene()) boot();
  else {
    var n = 0;
    var iv = setInterval(function () {
      if (typeof cc !== "undefined" && cc.director && cc.director.getScene()) {
        clearInterval(iv); boot();
      } else if (++n > 300) clearInterval(iv);
    }, 100);
  }
})();
